function renderCalendar(social=false){
 const month=new Date(2026,8+calendarOffset,1),label=month.toLocaleDateString('en-US',{month:'long',year:'numeric'}),start=(month.getDay()+6)%7;
 const count=calendarMode==='week'?7:35;const base=calendarMode==='week'?14:1-start;
 const planned=keywords.filter(k=>k.planned);
 let cells=Array.from({length:count},(_,i)=>{const d=new Date(month.getFullYear(),month.getMonth(),base+i),n=d.getDate(),inMonth=d.getMonth()===month.getMonth();const eventIndex=Math.round((Date.UTC(d.getFullYear(),d.getMonth(),n)-Date.UTC(2026,8,14))/86400000);const k=planned[eventIndex];const has=inMonth&&eventIndex>=0&&eventIndex<(social?topics.length:planned.length);return `<div class="calendar-cell ${!inMonth?'other-month':''} ${n===14&&calendarOffset===0&&inMonth?'today':''}"><span class="day-number">${n}</span>${has?`<button class="calendar-event ${social?'social-event':''}" data-${social?'topic':'keyword'}="${social?eventIndex:k.id}"><small>${social?'02:00 PM · Social':'08:00 AM · SEO'}</small><strong>${esc(social?topics[eventIndex]:k.term)}</strong><span>${social?'Planned':k.difficulty}</span></button>`:'<span class="open-slot">Open slot</span>'}</div>`}).join('');
 return heading(social?'A consistent rhythm for every channel.':'Plan the SEO work before it gets published.',social?'Organize recurring themes and coordinated social content in one publishing calendar.':'Organize keywords, article production, and publishing dates into a steady pipeline.',button(social?'Add social topic':'Add keyword',social?'new-topic':'new-keyword','primary-button'))+
 `<section class="card module-card"><div class="calendar-toolbar"><div><h3>${label}</h3><span>${social?topics.length+' social topics':planned.length+' planned keywords'} · Preview calendar</span></div><div class="calendar-controls"><div class="filter-tabs"><button data-calendar-mode="week" aria-pressed="${calendarMode==='week'}">Week</button><button data-calendar-mode="month" aria-pressed="${calendarMode==='month'}">Month</button></div>${button('Today','calendar-today')}<button class="square-button" data-action="calendar-prev" aria-label="Previous month">${icon('chevron')}</button><button class="square-button" data-action="calendar-next" aria-label="Next month">${icon('chevron')}</button></div></div><div class="calendar-scroll"><div class="calendar-grid ${calendarMode}">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="weekday">${d}</div>`).join('')}${cells}</div></div></section>`;
}
