 return heading('Understand your search performance.','Clicks, impressions, queries, and the pages people discover in search.')+stats([['Total clicks','8,500','Illustrative · September'],['Impressions','126,400','Across search results'],['Average CTR','6.7%','Click-through rate'],['Average position','14.2','Across tracked queries']])+`<div class="module-grid">${card('Search performance',lineChart())}${card('Top search queries',keywords.slice(0,5).map((k,i)=>row(k.term,`${k.volume.toLocaleString()} impressions`,`${[860,745,620,510,420][i]} clicks`)).join(''))}</div>`+card('Top pages',table(['Page','Clicks','Impressions','CTR'],[['/blog/ai-search-visibility','1,840','24,500','7.5%'],['/blog/seo-content-calendar','1,320','18,200','7.3%'],['/blog/technical-seo-checklist','980','16,100','6.1%'],['/','850','14,300','5.9%']]))+`<div class="notice-line">${icon('link')}Search Console is not connected in this preview. ${link('Review connections','integration')}</div>`;
