function settingsForm(title,items,key){const values=readSaved(key,{});return heading(title,'These draft preferences are saved on this device.')+card('Preferences',`<form data-settings-form="${key}">${items.map(([label,name])=>`<label class="setting-row"><span>${label}</span><input type="checkbox" name="${name}" ${values[name]!==false?'checked':''}></label>`).join('')}<label class="form-field">Timezone<select name="Timezone">${['Asia/Kolkata','UTC','America/New_York','Europe/London'].map(t=>`<option ${values.Timezone===t?'selected':''}>${t}</option>`).join('')}</select></label><button class="primary-button">Save preferences</button></form>`,'','form-card')}
function renderSetup(){
 if(route==='author')return heading('Put real expertise behind your content.','Add author details that help readers and search engines understand who is speaking.')+profileForm(true);
 if(route==='business-profile')return heading('Keep your content grounded in your business.','Manage your business information, brand context, target keywords, and content preferences.')+`<div class="module-grid">${profileForm(false)}${card('Brand & content context',row('SEO Keywords','Build a keyword plan from relevant search demand.',`${keywords.length} ideas`,'discovery')+row('Competitive Edge','Add the brands and alternatives your audience compares.',badge('Configure','neutral'),'settings')+row('Content Settings','Keep your voice and approval preferences consistent.',badge('Review','lilac'),'settings')+row('Author Profile','Add a real name, bio, and credentials.',badge('Setup needed','gold'),'author')+row('Ranking & Analysis','Understand visibility across search and AI engines.',arrow,'share-of-voice')+`<div class="brand-swatches"><i style="background:#12192d"></i><i style="background:#029bd1"></i><i style="background:#90d698"></i><i style="background:#ffd181"></i><span>Dashboard palette · Inter</span></div>`)}</div>`;
 if(route==='documentation')return heading('From draft to your website.','A simple publishing workflow, with a review step before anything goes live.')+`<div class="module-grid">${card('Publishing documentation',`<div class="documentation"><h3>1. Connect your destination</h3><p>Open Website Integration in the original Uplift AI workspace and choose your website platform. Follow the platform’s connection steps.</p><h3>2. Confirm your content settings</h3><p>Review your brand context, author information, categories, and preferred publishing schedule.</p><h3>3. Review your generated article</h3><p>Check the title, content, SEO score, sources, and internal links. Make your edits in Content Library.</p><h3>4. Approve and schedule</h3><p>Choose a publishing date and destination in the connected workspace. Confirm that the published page looks right.</p></div>`)}${card('Before you publish',row('Article accuracy','Verify facts, examples, and citations.',badge('Review','gold'))+row('Author and brand','Confirm the byline and business details.',badge('Review','gold'))+row('Search metadata','Check the title, description, and canonical URL.',badge('Review','gold'))+row('Destination','Confirm the website and publishing date.',badge('Review','gold'))+`<a class="secondary-button" href="https://dashboard.upliftai.co/dashboard/publish-console/documentation" target="_blank" rel="noopener">Open original documentation ${arrow}</a>`)}</div>`;
 return heading('Bring your content to your website.','Connect your destination, confirm your publishing workflow, and keep control of what goes live.')+`<div class="module-grid">${card('Website publishing',`<div class="connection-summary"><span class="workspace-mark large">U</span><div><h3>upliftai.co</h3><p class="muted-copy">Uplift AI website</p></div></div><div class="connection-footer">${badge('Not connected','neutral')}<button class="secondary-button" data-connection="Website publishing">Connection details</button></div>`)}${card('Reporting connections',row('Google Search Console','Search performance and indexing.',badge('Not connected','neutral'),'search-console')+row('Google Business Profile','Local visibility, posts, and reviews.',badge('Not connected','neutral'),'google')+row('Social accounts','Instagram, Facebook, LinkedIn, and X.',badge('Not connected','neutral'),'connections'))}</div>`+card('Your publishing checklist',row('Confirm business information','Keep generated content aligned with your business.',arrow,'business-profile')+row('Configure an author','Add your expertise and credentials.',arrow,'author')+row('Review publishing documentation','Understand the connection and review steps.',arrow,'documentation'));
}
function profileForm(author){const key=author?'author':'profile',v=readSaved(key,author?{}:{name:'Uplift AI',website:'https://www.upliftai.co/',type:'SEO & AI visibility software',about:'Uplift AI brings SEO research, content creation, publishing, local visibility, and AI search insights into one workspace.'});return card(author?'Author profile':'Business information',`<form data-profile-form="${key}">${(author?[['Full name','name','Your author name'],['Role or title','role','e.g. SEO strategist'],['Credentials','credentials','Relevant experience or qualifications']]:[['Business name','name','Business name'],['Website','website','https://'],['Business type','type','What does your business do?']]).map(([l,k,p])=>`<label class="form-field">${l}<input name="${k}" value="${esc(v[k]||'')}" placeholder="${p}" ${k==='name'?'required':''} maxlength="150"></label>`).join('')}<label class="form-field">${author?'Author bio':'About the business'}<textarea name="about" rows="5" maxlength="1800" placeholder="${author?'Share the experience behind your content.':'Describe your business and audience.'}">${esc(v.about||'')}</textarea></label><div class="form-footer"><small>Saved only in this design preview.</small><button class="primary-button">Save ${author?'author':'business'} profile</button></div></form>`)}
function renderSettings(){
 if(route==='settings')return settingsForm('Workspace preferences',[['Require approval before publishing','Approval'],['Include internal linking suggestions','Internal links'],['Include AI visibility insights','AI insights'],['Show weekly performance summary','Weekly summary']], 'settings');
 if(route==='sitemap')return heading('Keep your published pages discoverable.','Review the content URLs that belong in your website’s sitemap.')+card('Sitemap preview',`<div class="inline-toolbar"><p class="muted-copy">Illustrative URLs. A live sitemap becomes available after website integration.</p>${button('Export URLs','export-sitemap')}</div>`+table(['URL','Content type','Status'],articles.filter(a=>a.status==='Published').map(a=>[`upliftai.co/blog/${a.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/-$/,'')}`,a.category,badge('Preview','neutral')])));
 if(route==='security')return heading('Account & security','Manage account access in your original Uplift AI workspace.')+card('Your account',row('Authentication','Sign-in and account security are managed by the original application.',badge('Managed externally','neutral'))+row('Connected accounts','Review the services connected to your workspace.',arrow,'connections')+`<a class="secondary-button" href="https://dashboard.upliftai.co/dashboard/project/settings?tab=account" target="_blank" rel="noopener">Open account & security ${arrow}</a>`,'','form-card');
 return heading('Your Uplift AI account','A focused home for your workspace and appearance.')+`<div class="module-grid">${card('Workspace',`<div class="account-hero"><span class="workspace-mark large">U</span><div><h3>Uplift AI</h3><p>upliftai.co</p></div>${badge('Design preview','blue')}</div>`+row('Business profile','Business information and content context.',arrow,'business-profile')+row('Account & security','Manage your sign-in in the original application.',arrow,'security'))}${card('Appearance',`<p class="muted-copy">Choose the appearance that feels right for your workspace.</p><div class="appearance-options"><button data-appearance="light" aria-pressed="${!document.body.classList.contains('dark')}"><span class="appearance-swatch light"></span>Light</button><button data-appearance="dark" aria-pressed="${document.body.classList.contains('dark')}"><span class="appearance-swatch dark"></span>Dark</button></div>`)}</div>`;
}
function renderModule(){
 const group=routes.find(r=>r.id===route).group;
 $('#module-view').innerHTML=route==='library'?renderLibrary():route==='calendar'?renderCalendar():route==='audit'?renderAudit():group==='ai'?renderAI():group==='social'?renderSocial():group==='google'?renderGoogle():group==='setup'?renderSetup():group==='settings'?renderSettings():renderAnalytics();
}
function articleDetail(id){const a=articles.find(x=>x.id===Number(id));if(!a)return;openDialog(a.title,`<div class="article-meta">${statusBadge(a.status)}<span>${a.minutes} min read</span><span>SEO ${a.score}/100</span></div><p class="detail-intro">Edit this preview article. Changes stay on this device.</p><form id="article-form" data-id="${a.id}"><label class="form-field">Title<input name="title" required maxlength="160" value="${esc(a.title)}"></label><label class="form-field">Content<textarea name="body" rows="10">${esc(a.body||`${a.title}\n\nA strong content workflow starts with a useful question. Understand what your audience needs, create a clear answer, and make it easy to discover.\n\nStart with your audience\nReview the search intent behind your target topic. Look for the decisions people are trying to make and the details that would help them move forward.\n\nBuild a repeatable workflow\nBring keyword research, editorial review, and publishing into one plan. Use Uplift AI to organize the work, then verify the final details before publication.\n\nMeasure and improve\nTrack search performance and AI visibility over time. Use what you learn to refresh content and choose your next topics.`)}</textarea></label><label class="form-field">Review status<select name="status">${['Draft','In review','Scheduled','Published'].map(s=>`<option ${s===a.status?'selected':''}>${s}</option>`).join('')}</select></label><div class="form-footer"><small>This does not publish to your website.</small><button class="primary-button">Save draft changes</button></div></form>`)}
function topicDetail(i){const t=topics[Number(i)];if(!t)return;openDialog(t,`<div class="article-meta">${badge('Preview content','lilac')}<span>Social content set</span></div><p class="detail-intro">Platform-ready copy for this draft. Review before using it in your live channels.</p><div class="filter-tabs" id="social-preview-tabs">${platformNames.map((p,j)=>`<button data-social-preview="${j}" data-topic-index="${i}" aria-pressed="${j===0}">${p}</button>`).join('')}</div><div id="social-preview-copy" class="social-preview-copy"><h3>${esc(t)}</h3><p>${esc(socialCopy(t,0))}</p></div>${button('Copy caption','copy-caption')}`)}
function socialCopy(t,i){return i===3?`${t}. Turn research into useful content, keep your publishing consistent, and understand how your brand appears in AI search. Explore Uplift AI at upliftai.co.`:`${t}\n\nBetter visibility starts with useful content and a consistent process. Bring your keyword research, content planning, publishing, and AI visibility into one workspace with Uplift AI.\n\nStart with one question your audience is asking. Build a clear answer. Review it. Publish it. Learn from the results.\n\nExplore upliftai.co${i===0?'\n\n#UpliftAI #SEO #AIVisibility #ContentStrategy':''}`}
function newContent(){openDialog('Create content',`<p class="detail-intro">Add a new article to your local design preview.</p><form id="new-content-form"><label class="form-field">Article title<input name="title" required maxlength="160" placeholder="What would you like to write about?"></label><label class="form-field">Category<select name="category">${['AI visibility','SEO fundamentals','Content strategy','Technical SEO','Local SEO','Social media','Product guides'].map(c=>`<option>${c}</option>`).join('')}</select></label><button class="primary-button">Create draft</button></form>`)}
function newKeyword(){openDialog('Add a keyword',`<p class="detail-intro">Add a keyword to the preview content plan.</p><form id="keyword-form"><label class="form-field">Keyword<input name="term" required maxlength="100" placeholder="e.g. AI visibility for small businesses"></label><label class="form-field">Estimated monthly searches<input name="volume" type="number" min="0" max="10000000" value="0" required></label><button class="primary-button">Add to plan</button></form>`)}
function downloadCSV(name,rows){const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Report downloaded.')}
function setTheme(dark){document.body.classList.toggle('dark',dark);$('#theme').setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');try{localStorage.setItem('uplift-theme',dark?'dark':'light')}catch{}if(route==='account')renderModule()}

// Delegate actions so every route keeps the same interaction behavior.
document.addEventListener('click',e=>{
 const b=e.target.closest('button,[data-route]');if(!b)return;
 if(b.dataset.route){location.hash=b.dataset.route;return}
 if(b.dataset.article!==undefined)return articleDetail(b.dataset.article);
 if(b.dataset.topic!==undefined)return topicDetail(b.dataset.topic);
 if(b.dataset.keyword!==undefined){const k=keywords.find(x=>x.id===Number(b.dataset.keyword));return openDialog(k.term,`<p class="detail-intro">Keyword-led content planning · Preview</p>${row('Monthly searches','Illustrative search demand',k.volume.toLocaleString())}${row('Difficulty','Estimated competition',badge(k.difficulty,'gold'))}${row('Publishing time','September 2026','08:00 AM')}${link('Review content library','library','secondary-button')}`)}
 if(b.dataset.planKeyword!==undefined){const k=keywords.find(x=>x.id===Number(b.dataset.planKeyword));k.planned=true;save('keywords',keywords);renderModule();toast('Keyword added to your preview plan.');return}
 if(b.dataset.filter){libraryFilter=b.dataset.filter;renderModule();return}
 if(b.dataset.calendarMode){calendarMode=b.dataset.calendarMode;renderModule();return}
 if(b.dataset.auditTab){auditTab=b.dataset.auditTab;renderModule();return}
 if(b.dataset.appearance){setTheme(b.dataset.appearance==='dark');return}
 if(b.dataset.socialPreview!==undefined){const i=Number(b.dataset.socialPreview);$('#social-preview-copy').innerHTML=`<h3>${esc(topics[b.dataset.topicIndex])}</h3><p>${esc(socialCopy(topics[b.dataset.topicIndex],i))}</p>`;document.querySelectorAll('[data-social-preview]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));return}
 if(b.dataset.evidence!==undefined){const p=aiPrompts[b.dataset.evidence];return openDialog('Prompt evidence',`<p class="detail-intro">Illustrative evidence preview. No live scan has been run for this workspace.</p><h3>${p[0]}</h3>${row('Prompt type','',p[1])}${row('Result','',badge(p[2],p[2]==='Brand cited'?'green':'neutral'))}${row('AI engines','','ChatGPT · Gemini')}<p class="report-note">A live result would show the AI response, cited URLs, and scan timestamp here. Connect the original workspace to collect verified evidence.</p>`)}
 if(b.dataset.connection)return openDialog(b.dataset.connection,`<p class="detail-intro">Connect ${esc(b.dataset.connection)} in the original Uplift AI application. This design preview does not request credentials or change your live connections.</p>${row('Workspace','','Uplift AI')}${row('Preview connection','','Not connected')}<a class="primary-button" href="https://dashboard.upliftai.co/dashboard/${b.dataset.connection==='Google Business Profile'?'google-my-business':platformNames.includes(b.dataset.connection)?'social/connections':'publish-console'}" target="_blank" rel="noopener">Open connection setup ${arrow}</a>`);
 const action=b.dataset.action;if(!action)return;
 if(action==='new-content')return newContent();
 if(action==='new-keyword')return newKeyword();
 if(action==='new-topic')return openDialog('Add a social topic',`<p class="detail-intro">Add an idea to your preview topic plan.</p><form id="topic-form"><label class="form-field">Topic<input name="topic" required maxlength="150" placeholder="The idea you want to share"></label><button class="primary-button">Add topic</button></form>`);
 if(action==='sort'){sortNewest=!sortNewest;renderModule()}
 if(action==='calendar-prev'||action==='calendar-next'||action==='calendar-today'){calendarOffset=action==='calendar-today'?0:calendarOffset+(action==='calendar-next'?1:-1);renderModule()}
 if(action==='export-articles')downloadCSV('uplift-content-library',[['Title','Category','Status','SEO score'],...articles.map(a=>[a.title,a.category,a.status,a.score])]);
 if(action==='export-sitemap')downloadCSV('uplift-sitemap-preview',[['Title','Status'],...articles.filter(a=>a.status==='Published').map(a=>[a.title,a.status])]);
 if(action==='audit-details')openDialog('SEO audit details',`<p class="detail-intro">This report demonstrates how audit results fit into the new dashboard design. Scores and issues are illustrative.</p>${row('Website','','upliftai.co')}${row('Audit status','','Preview report')}<a class="primary-button" href="https://dashboard.upliftai.co/dashboard/seo-audit" target="_blank" rel="noopener">Run an audit in Uplift AI ${arrow}</a>`);
 if(action==='copy-caption')copyText($('#social-preview-copy').innerText);
});
document.addEventListener('submit',e=>{
 const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const d=new FormData(f);
 if(f.id==='new-content-form'){const title=d.get('title').trim();if(!title){toast('Enter an article title.');return}const id=Math.max(...articles.map(a=>a.id))+1;articles.push({id,title,category:d.get('category'),status:'Draft',score:0,minutes:0,date:'2026-09-14',body:''});save('articles',articles);dialog.close();location.hash='library';if(route==='library')renderModule();toast('New draft created on this device.');return}
 if(f.id==='article-form'){const a=articles.find(x=>x.id===Number(f.dataset.id)),title=d.get('title').trim();if(!title){toast('Enter an article title.');return}a.title=title;a.body=d.get('body');a.status=d.get('status');save('articles',articles);dialog.close();route==='home'?renderHome():renderModule();toast('Preview article saved. Nothing was published.');return}
 if(f.id==='keyword-form'){const term=d.get('term').trim();if(!term){toast('Enter a keyword.');return}keywords.push({id:Math.max(...keywords.map(k=>k.id))+1,term,volume:Number(d.get('volume')),difficulty:'Unscored',planned:true});save('keywords',keywords);dialog.close();location.hash='discovery';if(route==='discovery')renderModule();toast('Keyword added to your plan.');return}
 if(f.id==='topic-form'){const t=d.get('topic').trim();if(!t){toast('Enter a social topic.');return}topics.push(t);save('topics',topics);dialog.close();toast('Topic added to your preview plan.');location.hash='social-calendar';if(route==='social-calendar')renderModule();return}
 if(f.dataset.profileForm){save(f.dataset.profileForm,Object.fromEntries(d));toast('Profile saved on this device.');return}
 if(f.dataset.settingsForm){const values={};f.querySelectorAll('input[type=checkbox]').forEach(i=>values[i.name]=i.checked);values.Timezone=d.get('Timezone');save(f.dataset.settingsForm,values);toast('Preferences saved on this device.')}
});
document.addEventListener('input',e=>{if(e.target.id==='library-search'){libraryQuery=e.target.value;const start=e.target.selectionStart;renderModule();$('#library-search').focus();$('#library-search').setSelectionRange(start,start)}});
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.')}catch{toast('Clipboard unavailable. Select the text and copy it manually.')}}
$('.skip-link').onclick=e=>{e.preventDefault();$('#page-content').focus();$('#page-content').scrollIntoView({block:'start'})};
$('#close-dialog').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.addEventListener('click',e=>{if(e.target.closest('#detail-dialog a[href^="#"]'))dialog.close();if(!e.target.closest('.search'))$('#search-results').hidden=true});
$('#theme').onclick=()=>setTheme(!document.body.classList.contains('dark'));
$('.collapse').onclick=()=>{const expanded=$('.sidebar').classList.toggle('expanded');$('.collapse').setAttribute('aria-expanded',expanded);$('.collapse').setAttribute('aria-label',expanded?'Collapse navigation':'Expand navigation')};
$('#share').onclick=()=>openDialog('Share workspace',`<p class="detail-intro">Copy a link to this draft. Access follows the dashboard’s existing sharing settings.</p><label class="form-field">Dashboard link<input readonly value="${esc(location.href)}" id="share-url"></label><button class="primary-button" id="copy-link">Copy link</button>`);
document.addEventListener('click',e=>{if(e.target.id==='copy-link')copyText($('#share-url').value)});
$('#search').oninput=e=>{const q=e.target.value.trim().toLowerCase();if(!q){$('#search-results').hidden=true;return}const found=routes.filter(r=>r.label.toLowerCase().includes(q)).map(r=>({title:r.label,sub:groups[r.group].name,route:r.id})).concat(articles.filter(a=>a.title.toLowerCase().includes(q)).map(a=>({title:a.title,sub:'Content Library',article:a.id}))).slice(0,8);$('#search-results').hidden=false;$('#search-results').innerHTML=found.length?found.map(f=>f.route?`<a href="#${f.route}"><strong>${esc(f.title)}</strong><small>${f.sub}</small></a>`:`<button data-article="${f.article}"><strong>${esc(f.title)}</strong><small>${f.sub}</small></button>`).join(''):'<p>No matches. Try “content”, “social”, or “audit”.</p>'};
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#search').focus()}if(e.key==='Escape')$('#search-results').hidden=true});
window.addEventListener('hashchange',navigate);
const savedTopics=readSaved('topics',null);if(savedTopics?.length)topics.splice(0,topics.length,...savedTopics);
renderShell();try{setTheme(localStorage.getItem('uplift-theme')==='dark')}catch{}navigate();
